output_text:
[
  {
    "id": "must_take_entry_cart",
    "text": "A shopper is obliged to pick up a cart at the start of the trip and keep shopping as a cart user.",
    "abstraction": {
      "state_properties": {
        "entranceCartArea": {
          "and": [
            "at(1,7)",
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        }
      },
      "events": {
        "pickUpCart": {
          "pre": {
            "and": [
              "entranceCartArea",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickUpCart"
    }
  },
  {
    "id": "exit_with_cart",
    "text": "A shopper is forbidden to leave the store without the cart they used during the trip.",
    "abstraction": {
      "state_properties": {
        "exitCell": "at(11,7)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exitCell",
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_in_single_file_aisle",
    "text": "Carts are forbidden in single-file aisles, identified as cells whose horizontal free width is only one cell.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "cartInSingleFileAisle": {
          "and": [
            "singleFileAisle",
            "hasCart"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartInSingleFileAisle"
    }
  },
  {
    "id": "no_push_cart_into_single_file",
    "text": "A shopper is forbidden to push a cart from an open aisle into a single-file aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "openAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        }
      },
      "events": {
        "pushCartIntoSingleFileAisle": {
          "pre": {
            "and": [
              "openAisle",
              "hasCart",
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "singleFileAisle",
              "hasCart"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pushCartIntoSingleFileAisle"
    }
  },
  {
    "id": "park_cart_at_single_file_mouth",
    "text": "When a cart user reaches the mouth of the single-file shelf aisle, they are obliged to park the cart there before proceeding on foot.",
    "abstraction": {
      "state_properties": {
        "singleFileMouth": {
          "and": [
            "at(6,3)",
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        },
        "atSingleFileMouthWithCart": {
          "and": [
            "singleFileMouth",
            "hasCart"
          ]
        }
      },
      "events": {
        "parkCartAtSingleFileMouth": {
          "pre": {
            "and": [
              "singleFileMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "atSingleFileMouthWithCart",
      "discharge": "parkCartAtSingleFileMouth"
    }
  },
  {
    "id": "retrieve_cart_after_single_file",
    "text": "After parking a cart to enter a single-file aisle, the shopper is obliged to retrieve that cart before leaving the store.",
    "abstraction": {
      "state_properties": {
        "singleFileMouth": {
          "and": [
            "at(6,3)",
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        }
      },
      "events": {
        "parkCartAtSingleFileMouth": {
          "pre": {
            "and": [
              "singleFileMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCartAtSingleFileMouth": {
          "pre": {
            "and": [
              "singleFileMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtSingleFileMouth",
      "discharge": "retrieveCartAtSingleFileMouth"
    }
  },
  {
    "id": "cart_required_in_two_wide_shelf_bay",
    "text": "In two-wide shelf bays, shoppers are forbidden to be without a cart, distinguishing them from one-wide aisles where carts do not fit.",
    "abstraction": {
      "state_properties": {
        "twoWideAisle": {
          "eq": [
            "freeWidthH",
            2
          ]
        },
        "twoWideShelfBay": {
          "and": [
            "twoWideAisle",
            "adjShelf"
          ]
        },
        "cartlessInTwoWideShelfBay": {
          "and": [
            "twoWideShelfBay",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartlessInTwoWideShelfBay"
    }
  },
  {
    "id": "do_not_detach_cart_in_constricted_place",
    "text": "A shopper is forbidden to detach or park a cart in a constricted place; cart parking should occur only in broad open aisles.",
    "abstraction": {
      "state_properties": {
        "horizontallyConstricted": {
          "le": [
            "freeWidthH",
            2
          ]
        },
        "verticallyConstricted": {
          "le": [
            "freeWidthV",
            2
          ]
        },
        "constrictedPlace": {
          "or": [
            "horizontallyConstricted",
            "verticallyConstricted"
          ]
        }
      },
      "events": {
        "detachCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "detachCart",
          "constrictedPlace"
        ]
      }
    }
  }
]
